<?php

use App\Filament\Resources\Orders\Pages\CreateOrder;
use App\Models\Department;
use App\Models\User;
use Database\Seeders\RolesAndPermissionsSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Livewire\Livewire;

uses(RefreshDatabase::class);

/**
 * Departments are matched by name, never by code: `code` is generated by
 * HasCode (MMG-DEP-000003), so filtering on 'SAL'/'MKT' returned nothing and
 * the Sales / Marketing dropdown rendered empty in production.
 */
beforeEach(function () {
    $this->seed(RolesAndPermissionsSeeder::class);
});

function orderActor(?int $departmentId = null): User
{
    $user = User::factory()->create(['department_id' => $departmentId]);
    $user->assignRole('Super Admin');

    return $user;
}

it('lists Sales and Marketing users with generated department codes', function () {
    $sales = Department::factory()->create(['name' => Department::SALES]);
    $marketing = Department::factory()->create(['name' => Department::MARKETING]);
    $finance = Department::factory()->create(['name' => 'Finance & Accounting']);

    $inactiveSalesUser = User::factory()->create(['department_id' => $sales->id, 'is_active' => false]);
    $inactiveMarketingUser = User::factory()->create(['department_id' => $marketing->id, 'is_active' => false]);
    $salesUser = User::factory()->create(['department_id' => $sales->id]);
    $marketingUser = User::factory()->create(['department_id' => $marketing->id]);
    $financeUser = User::factory()->create(['department_id' => $finance->id]);

    expect($sales->code)->not->toBe('SAL')
        ->and($marketing->code)->not->toBe('MKT');

    Livewire::actingAs(orderActor($sales->id))
        ->test(CreateOrder::class)
        ->assertFormFieldExists('sales_id', function ($field) use ($salesUser, $marketingUser, $financeUser, $inactiveSalesUser, $inactiveMarketingUser): bool {
            $options = $field->getOptions();

            return isset($options[$salesUser->id], $options[$marketingUser->id])
                && ! isset($options[$financeUser->id])
                && ! isset($options[$inactiveSalesUser->id], $options[$inactiveMarketingUser->id]);
        });
});

it('limits a user outside Sales and Marketing to Sales users', function () {
    $sales = Department::factory()->create(['name' => Department::SALES]);
    $marketing = Department::factory()->create(['name' => Department::MARKETING]);
    $finance = Department::factory()->create(['name' => 'Finance & Accounting']);

    $salesUser = User::factory()->create(['department_id' => $sales->id]);
    $marketingUser = User::factory()->create(['department_id' => $marketing->id]);

    Livewire::actingAs(orderActor($finance->id))
        ->test(CreateOrder::class)
        ->assertFormSet(['sales_id' => null])
        ->assertFormFieldExists('sales_id', fn ($field): bool => $field->getOptions() === [
            $salesUser->id => $salesUser->name,
        ]);
});

it('defaults the salesperson to the acting Sales user', function () {
    $sales = Department::factory()->create(['name' => Department::SALES]);
    $actor = orderActor($sales->id);

    Livewire::actingAs($actor)
        ->test(CreateOrder::class)
        ->assertFormSet(['sales_id' => $actor->id]);
});
